 * @dev Section A.3 of Intel V4 TDX DCAP API Library Documentation
 */
struct Header {
    uint16 version; // LE -> BE
    bytes2 attestationKeyType;
    bytes4 teeType;
    bytes2 qeSvn;
    bytes2 pceSvn;
    bytes16 qeVendorId;
    bytes20 userData;
}

/**
 * @notice The struct definition of EnclaveReport
