 * @param advisoryIDs The list of advisory IDs returned by the matching FMSPC TCB entry
 */
struct Output {
    uint16 quoteVersion; // serialized as BE, for EVM compatibility
    bytes4 tee;
    TCBStatus tcbStatus;
    bytes6 fmspcBytes;
    bytes quoteBody;
    string[] advisoryIDs;
}

