}

/// ========== CUSTOM TYPES ==========

/**
 * @title PCK Certificate Collateral
 * @param pckChain The Parsed PCK Certificate Chain
 * @param pckExtension Parsed Intel SGX Extension from the PCK Certificate
 */
struct PCKCollateral {
    X509CertObj[] pckChain;
