pragma solidity ^0.8.0;

import {Ownable} from "solady/auth/Ownable.sol";
import {console} from "forge-std/console.sol";
import "@openzeppelin/contracts/utils/math/SafeCast.sol";

import {MeasurementDao} from "./MeasurementDao.sol";
import {AutomataDcapAttestationFee} from "dcap-attestation/AutomataDcapAttestationFee.sol";
import {BELE} from "dcap-attestation/utils/BELE.sol";
import {BytesUtils} from "dcap-attestation/utils/BytesUtils.sol";
import {TEECacheVerifier} from "./TEECacheVerifier.sol";
import "dcap-attestation/types/Constants.sol";

/**
 * @notice verify quote from rollup
 */
contract DcapAttestationRouter is Ownable {
    using BytesUtils for bytes;

    uint16 private constant USER_DATA_V3_OFFSET = 333;
    uint16 private constant USER_DATA_V4_OFFSET = 533;
    uint16 private constant USER_DATA_V5_OFFSET = 539;

    address public dcapAttestation;
    address public measurementDao;
    bool public toVerifyMr;
    address public cacheVerifierAddr;
    bool public CacheOption;
    mapping(address => bool) _authorized;
    bool _isCallerRestricted = true;
    bool public toVerifyMrtd = false;

    error Forbidden();
    error InvalidAddress();
    error MrValidationFailed();
    error MRTDValidationFailed();

    modifier onlyAuthorized() {
        if (_isCallerRestricted && !_authorized[msg.sender]) {
            revert Forbidden();
        }
        _;
    }

    constructor(address _dcapAttestation, address _measurementDao, address _cacheVerifierAddr) {
        _initializeOwner(msg.sender);
        _setConfig(_dcapAttestation, _measurementDao, true, _cacheVerifierAddr, true);
    }

    function setConfig(
        address _dcapAttestation,
        address _measurementDao,
        bool _toVerifyMr,
        address _cacheVerifierAddr,
        bool _CacheOption
    ) external onlyOwner {
        _setConfig(_dcapAttestation, _measurementDao, _toVerifyMr, _cacheVerifierAddr, _CacheOption);
    }

    function setAuthorized(address caller, bool authorized) external onlyOwner {
        _authorized[caller] = authorized;
    }

    function enableCallerRestriction() external onlyOwner {
        _isCallerRestricted = true;
    }

    function disableCallerRestriction() external onlyOwner {
        _isCallerRestricted = false;
    }

    function verifyProof(bytes calldata aggrProof)
        external
        onlyAuthorized
        returns (uint32 _error_code, bytes32 commitment)
    {
        (_error_code, commitment) = _verifyProof(aggrProof);
    }

    function _setConfig(
        address _dcapAttestation,
        address _measurementDao,
        bool _toVerifyMr,
        address _cacheVerifierAddr,
        bool _CacheOption
    ) private {
        if (_dcapAttestation == address(0)) revert InvalidAddress();
        if (_measurementDao == address(0)) revert InvalidAddress();
        if (_cacheVerifierAddr == address(0)) revert InvalidAddress();
        dcapAttestation = _dcapAttestation;
        measurementDao = _measurementDao;
        toVerifyMr = _toVerifyMr;
        cacheVerifierAddr = _cacheVerifierAddr;
        CacheOption = _CacheOption;
    }

    function enableVerifyMRTD() external onlyOwner {
        toVerifyMrtd = true;
    }

    function disableVerifyMRTD() external onlyOwner {
        toVerifyMrtd = false;
    }

    function _verifyMeasurement(bytes calldata quote, uint16 quoteVersion) private view returns (bool) {
        bytes4 teeType = bytes4(quote.substring(4, 4));
        if (teeType == SGX_TEE) {
            return MeasurementDao(measurementDao).verifyMeasurementSGX(quote, quoteVersion);
        } else {
            if (toVerifyMrtd) {
                bool mrtdVerified = MeasurementDao(measurementDao).verifyMRTD(quote, quoteVersion);
                if (!mrtdVerified) {
                    revert MRTDValidationFailed();
                }
            }
            return MeasurementDao(measurementDao).verifyMeasurementTDX(quote, quoteVersion);
        }
    }

    function _verifyProof(bytes calldata aggrProof) private returns (uint32 _error_code, bytes32 commitment) {
        uint16 quoteVersion = SafeCast.toUint16(BELE.leBytesToBeUint(aggrProof[0:2]));
        if (toVerifyMr) {
            if (!_verifyMeasurement(aggrProof, quoteVersion)) {
                revert MrValidationFailed();
            }
        }
        bytes memory ecdsa256BitSignature;
        bytes memory ecdsaAttestationKey;
        bool success;
        bytes memory output;
        TEECacheVerifier CacheAttestation = TEECacheVerifier(cacheVerifierAddr);
        (ecdsa256BitSignature, ecdsaAttestationKey) = CacheAttestation.parseAttestationKey(aggrProof, quoteVersion);
        if (CacheOption && CacheAttestation.isInitialized(ecdsaAttestationKey)) {
            (_error_code, commitment) = CacheAttestation.verifyAndAttestOnChain(
                aggrProof, ecdsa256BitSignature, ecdsaAttestationKey, quoteVersion
            );
        } else {
            AutomataDcapAttestationFee attestation = AutomataDcapAttestationFee(dcapAttestation);
            (success, output) = attestation.verifyAndAttestOnChain(aggrProof);

            if (success) {
                if (CacheOption) CacheAttestation.initializeCache(ecdsaAttestationKey);
                _error_code = 0;
                uint256 offset;
                if (quoteVersion == 3) {
                    offset = USER_DATA_V3_OFFSET;
                } else if (quoteVersion == 4) {
                    offset = USER_DATA_V4_OFFSET;
                } else if (quoteVersion == 5) {
                    offset = USER_DATA_V5_OFFSET;
                } else {
                    _error_code = 1;
                }
                if (_error_code == 0) {
                    // extract user data from output generated by dcap attestation contract
                    assembly {
                        // 0x20: skip bytes header(32 byte)
                        commitment := mload(add(output, add(offset, 0x20)))
                    }
                } else {
                    commitment = bytes32(0);
                }
            } else {
                _error_code = 1;
                commitment = bytes32(0);
            }
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {Asn1Decode, NodePtr} from "../utils/Asn1Decode.sol";
import {BytesUtils} from "../utils/BytesUtils.sol";
import {DateTimeUtils} from "../utils/DateTimeUtils.sol";

/**
 * @title Solidity Structure representing X509 Certificates
 * @notice This is a simplified structure of a DER-decoded X509 Certificate
 */
struct X509CertObj {
    uint256 serialNumber;
    string issuerCommonName;
    uint256 validityNotBefore;
    uint256 validityNotAfter;
    string subjectCommonName;
    bytes subjectPublicKey;
    // the extension needs to be parsed further for PCK Certificates
    uint256 extensionPtr;
    bytes authorityKeyIdentifier;
    bytes subjectKeyIdentifier;
    // for signature verification in the cert chain
    bytes signature;
    bytes tbs;
}

// 2.5.4.3
bytes constant COMMON_NAME_OID = hex"550403";
// 2.5.29.35
bytes constant AUTHORITY_KEY_IDENTIFIER_OID = hex"551D23";
// 2.5.29.14
bytes constant SUBJECT_KEY_IDENTIFIER_OID = hex"551D0E";

/**
 * @title X509 Certificates Helper Contract
 * @notice This is a standalone contract that can be used by off-chain applications and smart contracts
 * to parse DER-encoded X509 certificates.
 * @dev This parser is only valid for ECDSA signature algorithm and p256 key algorithm.
 */
contract X509Helper {
    using Asn1Decode for bytes;
    using NodePtr for uint256;
    using BytesUtils for bytes;

    /// =================================================================================
    /// USE THE GETTERS BELOW IF YOU DON'T WANT TO PARSE THE ENTIRE X509 CERTIFICATE
    /// =================================================================================

    function getTbsAndSig(bytes calldata der) external pure returns (bytes memory tbs, bytes memory sig) {
        uint256 root = der.root();
        uint256 tbsParentPtr = der.firstChildOf(root);
        uint256 sigPtr = der.nextSiblingOf(tbsParentPtr);
        sigPtr = der.nextSiblingOf(sigPtr);

        tbs = der.allBytesAt(tbsParentPtr);
        sig = _getSignature(der, sigPtr);
    }

    function getSerialNumber(bytes calldata der) external pure returns (uint256 serialNum) {
        uint256 root = der.root();
        uint256 tbsParentPtr = der.firstChildOf(root);
        uint256 tbsPtr = der.firstChildOf(tbsParentPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        serialNum = _parseSerialNumber(der, tbsPtr);
    }

    function getIssuerCommonName(bytes calldata der) external pure returns (string memory issuerCommonName) {
        uint256 root = der.root();
        uint256 tbsParentPtr = der.firstChildOf(root);
        uint256 tbsPtr = der.firstChildOf(tbsParentPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        issuerCommonName = _getCommonName(der, tbsPtr);
    }

    function getCertValidity(bytes calldata der)
        external
        pure
        returns (uint256 validityNotBefore, uint256 validityNotAfter)
    {
        uint256 root = der.root();
        uint256 tbsParentPtr = der.firstChildOf(root);
        uint256 tbsPtr = der.firstChildOf(tbsParentPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        (validityNotBefore, validityNotAfter) = _getValidity(der, tbsPtr);
    }

    function getSubjectCommonName(bytes calldata der) external pure returns (string memory subjectCommonName) {
        uint256 root = der.root();
        uint256 tbsParentPtr = der.firstChildOf(root);
        uint256 tbsPtr = der.firstChildOf(tbsParentPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        subjectCommonName = _getCommonName(der, tbsPtr);
    }

    function getSubjectPublicKey(bytes calldata der) external pure returns (bytes memory pubKey) {
        uint256 root = der.root();
        uint256 tbsParentPtr = der.firstChildOf(root);
        uint256 tbsPtr = der.firstChildOf(tbsParentPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);
        pubKey = _getSubjectPublicKey(der, der.firstChildOf(tbsPtr));
    }

    function getExtensionPtr(bytes calldata der) external pure returns (uint256 extensionPtr) {
        extensionPtr = _getExtensionPtr(der);
    }

    /// @dev according to RFC 5280, the Authority Key Identifier is mandatory for CA certificates
    /// @dev if not present, this method returns 0x00
    function getAuthorityKeyIdentifier(bytes calldata der) external pure returns (bytes memory akid) {
        uint256 extensionPtr = _getExtensionPtr(der);
        uint256 extnValuePtr = _findExtensionValuePtr(der, extensionPtr, AUTHORITY_KEY_IDENTIFIER_OID);
        if (extnValuePtr != 0) {
            akid = _getAuthorityKeyIdentifier(der, extnValuePtr);
        }
    }

    /// @dev according to RFC 5280, the Subject Key Identifier is RECOMMENDED for CA certificates
    /// @dev Intel DCAP attestation certificates contain this extension
    /// @dev this value can be useful for checking CRLs without performing signature verification, which can be costly in terms of gas
    /// @dev we can simply use this value to check against the CRL's authority key identifier
    /// @dev if not present, this method returns 0x00
    function getSubjectKeyIdentifier(bytes calldata der) external pure returns (bytes memory skid) {
        uint256 extensionPtr = _getExtensionPtr(der);
        uint256 extValuePtr = _findExtensionValuePtr(der, extensionPtr, SUBJECT_KEY_IDENTIFIER_OID);

        if (extValuePtr != 0) {
            skid = _getSubjectKeyIdentifier(der, extValuePtr);
        }
    }

    /// x509 Certificates generally contain a sequence of elements in the following order:
    /// 1. tbs
    /// - 1a. version
    /// - 1b. serial number
    /// - 1c. siganture algorithm
    /// - 1d. issuer
    /// - - 1d(a). common name
    /// - - 1d(b). organization name
    /// - - 1d(c). locality name
    /// - - 1d(d). state or province name
    /// - - 1d(e). country name
    /// - 1e. validity
    /// - - 1e(a) notBefore
    /// - - 1e(b) notAfter
    /// - 1f. subject
    /// - - contains the same set of elements as 1d
    /// - 1g. subject public key info
    /// - - 1g(a). algorithm
    /// - - 1g(b). subject public key
    /// - 1h. Extensions
    /// 2. Signature Algorithm
    /// 3. Signature
    function parseX509DER(bytes calldata der) external pure returns (X509CertObj memory cert) {
        uint256 root = der.root();

        uint256 tbsParentPtr = der.firstChildOf(root);
        cert.tbs = der.allBytesAt(tbsParentPtr);

        uint256 tbsPtr = der.firstChildOf(tbsParentPtr);

        tbsPtr = der.nextSiblingOf(tbsPtr);

        cert.serialNumber = _parseSerialNumber(der, tbsPtr);

        tbsPtr = der.nextSiblingOf(tbsPtr);
        tbsPtr = der.nextSiblingOf(tbsPtr);

        cert.issuerCommonName = _getCommonName(der, tbsPtr);

        tbsPtr = der.nextSiblingOf(tbsPtr);
        (cert.validityNotBefore, cert.validityNotAfter) = _getValidity(der, tbsPtr);

        tbsPtr = der.nextSiblingOf(tbsPtr);

        cert.subjectCommonName = _getCommonName(der, tbsPtr);

        tbsPtr = der.nextSiblingOf(tbsPtr);
        cert.subjectPublicKey = _getSubjectPublicKey(der, der.firstChildOf(tbsPtr));

        uint256 extensionPtr = der.nextSiblingOf(tbsPtr);
        if (bytes1(der[extensionPtr.ixs()]) == 0xA3) {
            cert.extensionPtr = extensionPtr;
            uint256 authorityKeyIdentifierPtr = _findExtensionValuePtr(der, extensionPtr, AUTHORITY_KEY_IDENTIFIER_OID);
            if (authorityKeyIdentifierPtr != 0) {
                cert.authorityKeyIdentifier = _getAuthorityKeyIdentifier(der, authorityKeyIdentifierPtr);
            }
            uint256 subjectKeyIdentifierPtr = _findExtensionValuePtr(der, extensionPtr, SUBJECT_KEY_IDENTIFIER_OID);
            if (subjectKeyIdentifierPtr != 0) {
                cert.subjectKeyIdentifier = _getSubjectKeyIdentifier(der, subjectKeyIdentifierPtr);
            }
        } else {
            revert("Extension is missing");
        }

        // tbs iteration completed
        // now we just need to look for the signature

        uint256 sigPtr = der.nextSiblingOf(tbsParentPtr);
        sigPtr = der.nextSiblingOf(sigPtr);
        cert.signature = _getSignature(der, sigPtr);
    }

    function _parseSerialNumber(bytes calldata der, uint256 serialNumberPtr) private pure returns (uint256 serial) {
        require(bytes1(der[serialNumberPtr.ixs()]) == 0x02, "not an integer");
        bytes memory serialBytes = der.bytesAt(serialNumberPtr);
        uint256 shift = 8 * (32 - serialBytes.length);
        serial = uint256(bytes32(serialBytes) >> shift);
    }

    function _getCommonName(bytes calldata der, uint256 rdnParentPtr) private pure returns (string memory) {
        // All we are doing here is iterating through a sequence of
        // one or many RelativeDistinguishedName (RDN) sets
        // which consists of one or many AttributeTypeAndValue sequences
        // we are only interested in the sequence with the CommonName type

        uint256 rdnPtr = der.firstChildOf(rdnParentPtr);
        bool commonNameFound = false;
        while (rdnPtr != 0) {
            uint256 sequencePtr = der.firstChildOf(rdnPtr);
            while (sequencePtr.ixl() <= rdnPtr.ixl()) {
                uint256 oidPtr = der.firstChildOf(sequencePtr);
                if (BytesUtils.compareBytes(der.bytesAt(oidPtr), COMMON_NAME_OID)) {
                    commonNameFound = true;
                    return string(der.bytesAt(der.nextSiblingOf(oidPtr)));
                } else if (sequencePtr.ixl() == rdnPtr.ixl()) {
                    break;
                } else {
                    sequencePtr = der.nextSiblingOf(sequencePtr);
                }
            }
            if (rdnPtr.ixl() < rdnParentPtr.ixl()) {
                rdnPtr = der.nextSiblingOf(rdnPtr);
            } else {
                rdnPtr = 0;
            }
        }

        if (!commonNameFound) {
            revert("Missing common name");
        }
    }

    function _getValidity(bytes calldata der, uint256 validityPtr)
        private
        pure
        returns (uint256 notBefore, uint256 notAfter)
    {
        uint256 notBeforePtr = der.firstChildOf(validityPtr);
        uint256 notAfterPtr = der.nextSiblingOf(notBeforePtr);
        notBefore = DateTimeUtils.fromDERToTimestamp(der.bytesAt(notBeforePtr));
        notAfter = DateTimeUtils.fromDERToTimestamp(der.bytesAt(notAfterPtr));
    }

    function _getSubjectPublicKey(bytes calldata der, uint256 subjectPublicKeyInfoPtr)
        private
        pure
        returns (bytes memory pubKey)
    {
        subjectPublicKeyInfoPtr = der.nextSiblingOf(subjectPublicKeyInfoPtr);
        pubKey = der.bitstringAt(subjectPublicKeyInfoPtr);
        if (pubKey.length != 65) {
            // TODO: we need to figure out how to handle key with prefix byte 0x02 or 0x03
            revert("compressed public key not supported");
        }
        pubKey = _trimBytes(pubKey, 64);
    }

    function _getAuthorityKeyIdentifier(bytes calldata der, uint256 extnValuePtr)
        private
        pure
        returns (bytes memory akid)
    {
        bytes memory extValue = der.bytesAt(extnValuePtr);

        // The AUTHORITY_KEY_IDENTIFIER consists of a SEQUENCE with the following elements
        // [0] - keyIdentifier (ESSENTIAL, but OPTIONAL as per RFC 5280)
        // [1] - authorityCertIssuer (OPTIONAL as per RFC 5280)
        // [2] - authorityCertSerialNumber (OPTIONAL as per RFC 5280)
        // since we are interested in only the key identifier
        // we iterate through the sequence until we find a tag matches with [0]

        uint256 parentPtr = extValue.root();
        uint256 ptr = extValue.firstChildOf(parentPtr);
        bytes1 contextTag = 0x80;
        while (true) {
            bytes1 tag = bytes1(extValue[ptr.ixs()]);
            if (tag == contextTag) {
                akid = extValue.bytesAt(ptr);
                break;
            }

            if (ptr.ixl() < parentPtr.ixl()) {
                ptr = extValue.nextSiblingOf(ptr);
            } else {
                break;
            }
        }
    }

    function _getSubjectKeyIdentifier(bytes calldata der, uint256 extValuePtr)
        private
        pure
        returns (bytes memory skid)
    {
        // The SUBJECT_KEY_IDENTIFIER simply consists of the KeyIdentifier of Octet String type (0x04)
        // so we can return the value as it is

        // check octet string tag
        require(der[extValuePtr.ixf()] == 0x04, "keyIdentifier must be of OctetString type");
        uint8 length = uint8(bytes1(der[extValuePtr.ixf() + 1]));
        skid = der[extValuePtr.ixf() + 2:extValuePtr.ixf() + 2 + length];
    }

    function _getSignature(bytes calldata der, uint256 sigPtr) private pure returns (bytes memory sig) {
        sigPtr = der.rootOfBitStringAt(sigPtr);

        sigPtr = der.firstChildOf(sigPtr);
        bytes memory r = _trimBytes(der.bytesAt(sigPtr), 32);

        sigPtr = der.nextSiblingOf(sigPtr);
        bytes memory s = _trimBytes(der.bytesAt(sigPtr), 32);

        sig = abi.encodePacked(r, s);
    }

    /// @dev remove unnecessary prefix from the input
    function _trimBytes(bytes memory input, uint256 expectedLength) private pure returns (bytes memory output) {
        uint256 n = input.length;
        if (n == expectedLength) {
            output = input;
        } else if (n < expectedLength) {
            output = new bytes(expectedLength);
            uint256 padLength = expectedLength - n;
            for (uint256 i = 0; i < n; i++) {
                output[padLength + i] = input[i];
            }
        } else {
            uint256 lengthDiff = n - expectedLength;
            output = input.substring(lengthDiff, expectedLength);
        }
    }

    function _getExtensionPtr(bytes calldata der) private pure returns (uint256 extensionPtr) {
        uint256 root = der.root();
        uint256 tbsParentPtr = der.firstChildOf(root);
        extensionPtr = der.firstChildOf(tbsParentPtr);
        // iterate through the sequence until we find the extension tag (0xA3)
        while (extensionPtr.ixl() <= tbsParentPtr.ixl()) {
            bytes1 tag = bytes1(der[extensionPtr.ixs()]);
            if (tag == 0xA3) {
                return extensionPtr;
            } else {
                if (extensionPtr.ixl() == tbsParentPtr.ixl()) {
                    revert("Extension is missing");
                } else {
                    extensionPtr = der.nextSiblingOf(extensionPtr);
                }
            }
        }
    }

    function _findExtensionValuePtr(bytes calldata der, uint256 extensionPtr, bytes memory oid)
        private
        pure
        returns (uint256)
    {
        uint256 parentPtr = der.firstChildOf(extensionPtr);
        uint256 ptr = der.firstChildOf(parentPtr);

        while (ptr != 0) {
            uint256 oidPtr = der.firstChildOf(ptr);
            if (der[oidPtr.ixs()] != 0x06) {
                revert("Missing OID");
            }
            if (BytesUtils.compareBytes(der.bytesAt(oidPtr), oid)) {
                return der.nextSiblingOf(oidPtr);
            }

            if (ptr.ixl() < parentPtr.ixl()) {
                ptr = der.nextSiblingOf(ptr);
            } else {
                ptr = 0;
            }
        }

        return 0; // not found
    }
}

//SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {LibString} from "solady/utils/LibString.sol";

import "../bases/QuoteVerifierBase.sol";
import "../bases/TDXModuleBase.sol";
import "../bases/tcb/TCBInfoV3Base.sol";
import "../types/V4Structs.sol";

struct FetchedCollateralsAndStatuses {
    X509CertObj[] parsedCerts;
    PCKCertTCB pckTcb;
    TCBLevelsObj[] tcbLevels;
    TDXModule tdxModule;
    TDXModuleIdentity[] tdxModuleIdentities;
    EnclaveIdTcbStatus qeTcbStatus;
}

/**
 * @title Automata DCAP QuoteV4 Verifier
 */
contract V4QuoteVerifier is QuoteVerifierBase, TCBInfoV3Base, TDXModuleBase {
    using LibString for bytes;
    using BytesUtils for bytes;

    constructor(address _ecdsaVerifier, address _router) QuoteVerifierBase(_router, 4) P256Verifier(_ecdsaVerifier) {}

    function verifyZkOutput(bytes calldata outputBytes)
        external
        view
        override
        returns (bool success, bytes memory output)
    {
        bytes4 teeType = bytes4(outputBytes[4:8]);
        if (teeType != SGX_TEE && teeType != TDX_TEE) {
            return (false, bytes("Unknown TEE type"));
        }

        uint16 outputLength = uint16(bytes2(outputBytes[0:2]));
        uint256 offset = 2 + outputLength;
        if (offset + VERIFIED_OUTPUT_COLLATERAL_HASHES_LENGTH != outputBytes.length) {
            return (false, "invalid output length");
        }
        bytes memory errorMessage;
        (success, errorMessage) = checkCollateralHashes(offset, outputBytes);
        output = success ? outputBytes[2:offset] : errorMessage;
    }

    function verifyQuote(Header calldata header, bytes calldata rawQuote)
        external
        view
        override
        returns (bool success, bytes memory output)
    {
        string memory reason;
        bytes memory rawQuoteBody;
        bytes memory rawQeReport;
        ECDSAQuoteV4AuthData memory authData;
        (success, reason, rawQuoteBody, rawQeReport, authData) = _parseV4Quote(header, rawQuote);
        if (!success) {
            return (false, bytes(reason));
        }

        // we parsed the quote except for the body
        // parse body then verify quote
        bytes memory rawHeader = rawQuote[0:HEADER_LENGTH];
        bytes memory rawBody;
        if (header.teeType == SGX_TEE) {
            EnclaveReport memory localEnclaveReport;
            (success, localEnclaveReport) = parseEnclaveReport(rawQuoteBody);
            if (!success) {
                return (false, bytes("local isv report length is incorrect"));
            }
            rawBody = rawQuote[HEADER_LENGTH:HEADER_LENGTH + ENCLAVE_REPORT_LENGTH];
            V4SGXQuote memory quote =
                V4SGXQuote({header: header, localEnclaveReport: localEnclaveReport, authData: authData});
            (success, output) = _verifySGXQuote(quote, rawHeader, rawBody, rawQeReport);
        } else if (header.teeType == TDX_TEE) {
            TD10ReportBody memory tdReport;
            (success, tdReport) = parseTD10ReportBody(rawQuoteBody);
            if (!success) {
                return (false, bytes("local td10 report length is incorrect"));
            }
            rawBody = rawQuote[HEADER_LENGTH:HEADER_LENGTH + TD_REPORT10_LENGTH];
            V4TDXQuote memory quote = V4TDXQuote({header: header, reportBody: tdReport, authData: authData});
            (success, output) = _verifyTDXQuote(quote, rawHeader, rawBody, rawQeReport);
        } else {
            return (false, bytes("Unknown TEE type"));
        }
    }

    function _parseV4Quote(Header calldata header, bytes calldata quote)
        private
        view
        returns (
            bool success,
            string memory reason,
            bytes memory rawQuoteBody,
            bytes memory rawQeReport,
            ECDSAQuoteV4AuthData memory authData
        )
    {
        bytes4 teeType = header.teeType;
        (success, reason) = validateHeader(header, quote.length, teeType == SGX_TEE || teeType == TDX_TEE);
        if (!success) {
            return (success, reason, rawQuoteBody, rawQeReport, authData);
        }

        // now that we are able to confirm that the provided quote is a valid V4 SGX/TDX quote
        // based on information found in the header
        // we continue parsing the remainder of the quote

        uint256 offset = HEADER_LENGTH;
        if (teeType == SGX_TEE) {
            offset += ENCLAVE_REPORT_LENGTH;
        } else {
            offset += TD_REPORT10_LENGTH;
        }
        rawQuoteBody = quote[HEADER_LENGTH:offset];

        if (quote.length < offset) {
            return (false, "quote body length is incorrect", rawQuoteBody, rawQeReport, authData);
        }

        // check authData length
        uint256 localAuthDataSize = BELE.leBytesToBeUint(quote[offset:offset + 4]);
        offset += 4;
        // we don't strictly require the auth data to be equal to the provided length
        // but this ignores any trailing bytes after the indicated length allocated for authData
        if (quote.length - offset < localAuthDataSize) {
            return (false, "quote auth data length is incorrect", rawQuoteBody, rawQeReport, authData);
        }

        // at this point, we have verified the length of the entire quote to be correct
        // parse authData
        (success, authData, rawQeReport) = parseAuthData(quote[offset:offset + localAuthDataSize]);
        if (!success) {
            return (false, "failed to parse authdata", rawQuoteBody, rawQeReport, authData);
        }
    }

    function _verifyCommon(
        bytes4 tee,
        bytes memory rawHeader,
        bytes memory rawBody,
        bytes memory rawQeReport,
        ECDSAQuoteV4AuthData memory authData
    ) private view returns (bool success, string memory reason, FetchedCollateralsAndStatuses memory ret) {
        // Step 0: Check QE Report Data
        success = verifyQeReportData(
            authData.qeReportCertData.qeReport.reportData,
            authData.ecdsaAttestationKey,
            authData.qeReportCertData.qeAuthData.data
        );
        if (!success) {
            return (success, "Invalid QEReport data", ret);
        }

        // Step 1: Fetch QEIdentity to validate TCB of the QE
        EnclaveIdTcbStatus qeTcbStatus;
        EnclaveId id = tee == SGX_TEE ? EnclaveId.QE : EnclaveId.TD_QE;
        EnclaveReport memory qeReport = authData.qeReportCertData.qeReport;
        (success, qeTcbStatus) = fetchQeIdentityAndCheckQeReport(id, qeReport);
        if (!success || qeTcbStatus == EnclaveIdTcbStatus.SGX_ENCLAVE_REPORT_ISVSVN_REVOKED) {
            return (success, "Verification failed by QEIdentity check", ret);
        }

        // Step 2: Fetch FMSPC TCB
        X509CertObj[] memory parsedCerts = authData.qeReportCertData.certification.pck.pckChain;
        PCKCertTCB memory pckTcb = authData.qeReportCertData.certification.pck.pckExtension;
        TcbId tcbId = tee == SGX_TEE ? TcbId.SGX : TcbId.TDX;
        (TCBLevelsObj[] memory tcbLevels, TDXModule memory tdxModule, TDXModuleIdentity[] memory tdxModuleIdentities) =
            pccsRouter.getFmspcTcbV3(tcbId, bytes6(pckTcb.fmspcBytes));

        // Step 3: verify cert chain
        success = verifyCertChain(pccsRouter, pccsRouter.crlHelperAddr(), parsedCerts);
        if (!success) {
            return (success, "Failed to verify X509 Chain", ret);
        }

        // Step 4: Signature Verification on local isv report and qereport by PCK
        bytes memory localAttestationData = abi.encodePacked(rawHeader, rawBody);
        success = attestationVerification(
            rawQeReport,
            authData.qeReportCertData.qeReportSignature,
            parsedCerts[0].subjectPublicKey,
            localAttestationData,
            authData.ecdsa256BitSignature,
            authData.ecdsaAttestationKey
        );
        if (!success) {
            return (success, "Failed to verify attestation and/or qe report signatures", ret);
        }

        ret.qeTcbStatus = qeTcbStatus;
        ret.parsedCerts = parsedCerts;
        ret.pckTcb = pckTcb;
        ret.tcbLevels = tcbLevels;
        ret.tdxModule = tdxModule;
        ret.tdxModuleIdentities = tdxModuleIdentities;
    }

    function _verifySGXQuote(
        V4SGXQuote memory quote,
        bytes memory rawHeader,
        bytes memory rawBody,
        bytes memory rawQeReport
    ) private view returns (bool success, bytes memory serialized) {
        // Step 1: Perform verification steps that are required for both SGX and TDX quotes
        string memory reason;
        FetchedCollateralsAndStatuses memory ret;
        (success, reason, ret) = _verifyCommon(quote.header.teeType, rawHeader, rawBody, rawQeReport, quote.authData);
        if (!success) {
            return (false, bytes(reason));
        }

        // Step 2: Check TCBStatus against isvs in the SGXComponent of the matching tcblevel
        TCBStatus tcbStatus;
        bool statusFound;
        uint256 tcbLevelSelected;
        for (uint256 i = 0; i < ret.tcbLevels.length; i++) {
            (statusFound, tcbStatus) = getSGXTcbStatus(ret.pckTcb, ret.tcbLevels[i]);
            if (statusFound) {
                tcbLevelSelected = i;
                break;
            }
        }
        if (!statusFound || tcbStatus == TCBStatus.TCB_REVOKED) {
            return (statusFound, bytes("Failed to locate a valid FMSPC TCB Status"));
        }

        // Step 3: Converge QEIdentity and FMSPC TCB Status
        tcbStatus = convergeTcbStatusWithQeTcbStatus(ret.qeTcbStatus, tcbStatus);

        Output memory output = Output({
            quoteVersion: quoteVersion,
            tee: SGX_TEE,
            tcbStatus: tcbStatus,
            fmspcBytes: bytes6(ret.pckTcb.fmspcBytes),
            quoteBody: rawBody,
            advisoryIDs: ret.tcbLevels[tcbLevelSelected].advisoryIDs
        });
        serialized = serializeOutput(output);
    }

    function _verifyTDXQuote(
        V4TDXQuote memory quote,
        bytes memory rawHeader,
        bytes memory rawBody,
        bytes memory rawQeReport
    ) private view returns (bool success, bytes memory serialized) {
        // Step 1: Perform verification steps that are required for both SGX and TDX quotes
        string memory reason;
        FetchedCollateralsAndStatuses memory ret;
        (success, reason, ret) = _verifyCommon(quote.header.teeType, rawHeader, rawBody, rawQeReport, quote.authData);
        if (!success) {
            return (false, bytes(reason));
        }

        // Step 2: Fetch FMSPC TCB
        // then get the TCB Status from the TDXComponent of the matching TCBLevel
        TCBStatus tcbStatus;
        uint256 tcbLevelSelected;
        (success, tcbStatus, tcbLevelSelected) = getTDXTcbStatus(ret.tcbLevels, ret.pckTcb, quote.reportBody.teeTcbSvn);
        if (!success) {
            return (false, bytes("Failed to locate a valid FMSPC TCB Status"));
        }

        // Step 3: Fetch TDXModule TCB Status
        TCBStatus tdxModuleStatus;
        uint8 tdxModuleVersion;
        bytes memory expectedMrSignerSeam;
        bytes8 expectedSeamAttributes;
        (success, tdxModuleStatus, tdxModuleVersion, expectedMrSignerSeam, expectedSeamAttributes) =
            checkTdxModuleTcbStatus(quote.reportBody.teeTcbSvn, ret.tdxModuleIdentities);
        if (!success || tdxModuleStatus == TCBStatus.TCB_REVOKED) {
            return (false, bytes("Failed to locate a valid TDXModule TCB Status"));
        }

        // Step 4: TDX Module check
        success = checkTdxModule(
            quote.reportBody.mrsignerSeam, expectedMrSignerSeam, quote.reportBody.seamAttributes, expectedSeamAttributes
        );
        if (!success) {
            return (false, bytes("TDXModule check failed"));
        }

        // Step 5: Converge TDXModule and FMSPC TCB Status
        tcbStatus = convergeTcbStatusWithTdxModuleStatus(tcbStatus, tdxModuleStatus);

        // Step 6: Converge QEIdentity and TDX TCB Status
        tcbStatus = convergeTcbStatusWithQeTcbStatus(ret.qeTcbStatus, tcbStatus);

        Output memory output = Output({
            quoteVersion: quoteVersion,
            tee: TDX_TEE,
            tcbStatus: tcbStatus,
            fmspcBytes: bytes6(ret.pckTcb.fmspcBytes),
            quoteBody: rawBody,
            advisoryIDs: ret.tcbLevels[tcbLevelSelected].advisoryIDs
        });
        serialized = serializeOutput(output);
    }

    /**
     * @dev set visibility to internal because this can be reused by V5 or above QuoteVerifiers
     */
    function parseTD10ReportBody(bytes memory reportBytes)
        internal
        pure
        returns (bool success, TD10ReportBody memory report)
    {
        success = reportBytes.length == TD_REPORT10_LENGTH;
        if (success) {
            report.teeTcbSvn = bytes16(reportBytes.substring(0, 16));
            report.mrSeam = reportBytes.substring(16, 48);
            report.mrsignerSeam = reportBytes.substring(64, 48);
            report.seamAttributes = bytes8(reportBytes.substring(112, 8));
            report.tdAttributes = bytes8(reportBytes.substring(120, 8));
            report.xFAM = bytes8(reportBytes.substring(128, 8));
            report.mrTd = reportBytes.substring(136, 48);
            report.mrConfigId = reportBytes.substring(184, 48);
            report.mrOwner = reportBytes.substring(232, 48);
            report.mrOwnerConfig = reportBytes.substring(280, 48);
            report.rtMr0 = reportBytes.substring(328, 48);
            report.rtMr1 = reportBytes.substring(376, 48);
            report.rtMr2 = reportBytes.substring(424, 48);
            report.rtMr3 = reportBytes.substring(472, 48);
            report.reportData = reportBytes.substring(520, 64);
        }
    }

    /**
     * @dev set visibility to internal because this can be reused by V5 or above QuoteVerifiers
     *
     * [0:64] bytes: ecdsa256BitSignature
     * [64:128] bytes: ecdsaAttestationKey
     * [128:130] bytes: qeReportCertType
     * [130:134] bytes: qeReportCertSize (X)
     * NOTE: the calculations below assume qeReportCertType == 6
     * [134:518] bytes: qeReport
     * [518:582] bytes: qeReportSignature
     * [582:584] bytes: qeAuthDataSize (Y)
     * [584:584+Y] bytes: qeAuthData
     * [584+Y:586+Y] bytes: pckCertType
     * NOTE: the calculations below assume pckCertType == 5
     * [586+Y:590+Y] bytes: certSize (Z)
     * [590+Y:590+Y+Z] bytes: certData
     */
    function parseAuthData(bytes calldata rawAuthData)
        internal
        view
        returns (bool success, ECDSAQuoteV4AuthData memory authDataV4, bytes memory rawQeReport)
    {
        authDataV4.ecdsa256BitSignature = rawAuthData[0:64];
        authDataV4.ecdsaAttestationKey = rawAuthData[64:128];

        uint256 qeReportCertType = BELE.leBytesToBeUint(rawAuthData[128:130]);
        if (qeReportCertType != 6) {
            return (false, authDataV4, rawQeReport);
        }
        uint256 qeReportCertSize = BELE.leBytesToBeUint(rawAuthData[130:134]);

        rawQeReport = rawAuthData[134:518];
        authDataV4.qeReportCertData.qeReportSignature = rawAuthData[518:582];

        uint16 qeAuthDataSize = uint16(BELE.leBytesToBeUint(rawAuthData[582:584]));
        authDataV4.qeReportCertData.qeAuthData.parsedDataSize = qeAuthDataSize;
        uint256 offset = 584;
        authDataV4.qeReportCertData.qeAuthData.data = rawAuthData[offset:offset + qeAuthDataSize];
        offset += qeAuthDataSize;

        uint16 certType = uint16(BELE.leBytesToBeUint(rawAuthData[offset:offset + 2]));
        // we only support certType == 5 for now...
        if (certType != 5) {
            return (false, authDataV4, rawQeReport);
        }

        authDataV4.qeReportCertData.certification.certType = certType;
        offset += 2;
        uint32 certDataSize = uint32(BELE.leBytesToBeUint(rawAuthData[offset:offset + 4]));
        offset += 4;
        authDataV4.qeReportCertData.certification.certDataSize = certDataSize;
        bytes memory rawCertData = rawAuthData[offset:offset + certDataSize];
        offset += certDataSize;

        if (offset - 134 != qeReportCertSize) {
            return (false, authDataV4, rawQeReport);
        }

        // parsing complete, now we need to decode some raw data

        (success, authDataV4.qeReportCertData.qeReport) = parseEnclaveReport(rawQeReport);
        if (!success) {
            return (false, authDataV4, rawQeReport);
        }

        (success, authDataV4.qeReportCertData.certification.pck) =
            getPckCollateral(pccsRouter.pckHelperAddr(), certType, rawCertData);
        if (!success) {
            return (false, authDataV4, rawQeReport);
        }
    }
}

